package cn.courselens;

import android.app.*;
import android.os.*;
import android.view.*;
import android.view.inputmethod.InputMethodManager;
import android.widget.*;
import androidx.core.view.*;
import java.util.*;
import static cn.courselens.AiChecks.*;

final class ChatMotionChecks {
 private static void await(Instrumentation i,java.util.function.BooleanSupplier ready,String error){long until=SystemClock.uptimeMillis()+6000;while(SystemClock.uptimeMillis()<until){i.waitForIdleSync();if(ready.getAsBoolean())return;SystemClock.sleep(32);}throw new AssertionError(error);}
 private static void tap(Instrumentation i,View view){int[] point=new int[2];main(i,()->view.getLocationOnScreen(point));long now=SystemClock.uptimeMillis();float x=point[0]+view.getWidth()/2f,y=point[1]+view.getHeight()/2f;for(int action:new int[]{MotionEvent.ACTION_DOWN,MotionEvent.ACTION_UP}){MotionEvent event=MotionEvent.obtain(now,SystemClock.uptimeMillis(),action,x,y,0);i.sendPointerSync(event);event.recycle();}i.waitForIdleSync();}
 private static void providers(Instrumentation i,MainActivity a)throws Exception{
  android.content.Context context=i.getTargetContext();DeepSeekKey legacy=new DeepSeekKey(context);legacy.save("synthetic-legacy-key");AiProviders store=new AiProviders(context);check(store.active().key.equals("synthetic-legacy-key"),"Legacy key was not inherited");
  store.save(new AiProviders.Config("compatible","合成供应商","https://example.com/v1","synthetic-model","synthetic-editable-key",false,false));store.save(new AiProviders.Config("second","第二供应商","https://second.example/v1","second-model","synthetic-second-key",false,true));store.select("compatible");store=new AiProviders(context);check(store.all().size()==3&&store.active().id.equals("compatible"),"Provider choice did not persist");
  for(Object value:context.getSharedPreferences("ai_providers",0).getAll().values())check(!String.valueOf(value).contains("synthetic-"),"Provider credentials are stored in plaintext");
  store.delete("deepseek");check(!legacy.configured()&&new AiProviders(context).all().size()==2,"Deleting legacy provider removed another configuration");
  main(i,()->call(a,"aiSettings"));SystemClock.sleep(300);main(i,()->((View)get(a,"root")).findViewWithTag("ai-provider-edit-compatible").performClick());SystemClock.sleep(300);
  main(i,()->{View root=(View)get(a,"root");check(((EditText)root.findViewWithTag("ai-key")).getText().toString().equals("synthetic-editable-key"),"Existing key is not editable");View save=root.findViewWithTag("ai-key-save"),delete=root.findViewWithTag("ai-key-delete");check(save.getParent()==delete.getParent()&&save.getTop()==delete.getTop()&&save.getLeft()<delete.getLeft(),"Provider actions are still vertically stacked");((EditText)root.findViewWithTag("ai-provider-model")).setText("edited-model");save.performClick();});SystemClock.sleep(300);check(new AiProviders(context).active().model.equals("edited-model"),"Provider edit did not persist");
 }
 static void run(Instrumentation i){
  Bundle result=new Bundle();int code=Activity.RESULT_CANCELED;MainActivity a=null;
  try{
   check(i.getTargetContext().getPackageName().equals("cn.courselens.qa"),"QA package required");a=NativeChecks.startQaActivity(i);MainActivity activity=a;await(i,activity::hasWindowFocus,"QA window did not gain focus");
   main(i,()->call(activity,"aiAssistant"));i.waitForIdleSync();View chat=(View)get(a,"root");AiComposer composer=chat.findViewWithTag("ai-composer");EditText message=chat.findViewWithTag("ai-message");int compact=composer.getHeight();
   List<Integer> heights=Collections.synchronizedList(new ArrayList<>());List<Float> menuFrames=Collections.synchronizedList(new ArrayList<>());ViewTreeObserver.OnPreDrawListener record=()->{heights.add(composer.getHeight());try{MainActivity.NavigationOverlay menu=(MainActivity.NavigationOverlay)get(activity,"aiAttachmentMenu");if(menu!=null)menuFrames.add(menu.motion.value);}catch(Exception e){throw new AssertionError(e);}return true;};main(i,()->{composer.getViewTreeObserver().addOnPreDrawListener(record);message.setText("合成动画草稿");message.setSelection(3);message.requestFocus();((InputMethodManager)activity.getSystemService(Activity.INPUT_METHOD_SERVICE)).showSoftInput(message,InputMethodManager.SHOW_IMPLICIT);});
   await(i,()->{WindowInsetsCompat insets=ViewCompat.getRootWindowInsets(composer);return insets!=null&&insets.isVisible(WindowInsetsCompat.Type.ime())&&composer.motion.value==1&&composer.getTranslationY()==0;},"Composer/IME did not finish expanding");int expanded=composer.getHeight();check(expanded>compact,"Composer did not expand");check(new HashSet<>(heights).size()>2,"Composer has no intermediate height frames");
   tap(i,chat.findViewWithTag("ai-attach"));MainActivity.NavigationOverlay popup=(MainActivity.NavigationOverlay)get(activity,"aiAttachmentMenu");check(popup!=null,"Attachment menu did not open");check(popup.body.findViewWithTag("ai-attach-plugin")==null,"Phone context remains in attachments");check(menuFrames.stream().anyMatch(p->p>0&&p<1),"Attachment menu has no intermediate entrance frames");await(i,()->popup.motion.value==1,"Attachment menu did not settle");tap(i,chat.findViewWithTag("ai-attach"));await(i,()->!popup.isAttachedToWindow(),"Second plus tap did not close the menu");check(get(a,"aiAttachmentMenu")==null,"Second plus tap reopened the menu");
   tap(i,chat.findViewWithTag("ai-attach"));MainActivity.NavigationOverlay withKeyboard=(MainActivity.NavigationOverlay)get(activity,"aiAttachmentMenu");check(withKeyboard!=null,"Menu could not reopen");
   android.graphics.Bitmap image=i.getUiAutomation().takeScreenshot();java.io.File directory=new java.io.File(a.getExternalFilesDir(null),"chat-motion");directory.mkdirs();try(java.io.FileOutputStream out=new java.io.FileOutputStream(new java.io.File(directory,"expanded.png"))){image.compress(android.graphics.Bitmap.CompressFormat.PNG,100,out);}image.recycle();
   main(i,()->((InputMethodManager)activity.getSystemService(Activity.INPUT_METHOD_SERVICE)).hideSoftInputFromWindow(message.getWindowToken(),0));await(i,()->composer.motion.value==0&&composer.getTranslationY()==0&&composer.getHeight()==compact&&!withKeyboard.isAttachedToWindow(),"Keyboard dismissal did not close the menu and composer");i.waitForIdleSync();check(composer.getHeight()==compact,"Compact height changed");check(message.getText().toString().equals("合成动画草稿")&&message.getSelectionStart()==3,"Draft or selection changed");
   main(i,()->{composer.getViewTreeObserver().removeOnPreDrawListener(record);chat.findViewWithTag("ai-history-button").performClick();});SystemClock.sleep(400);main(i,()->((SideNavigation)get(activity,"sideNavigation")).findViewWithTag("drawer-settings").performClick());SystemClock.sleep(400);main(i,activity::onBackPressed);SystemClock.sleep(300);check(get(a,"root")==chat,"Settings returned to timetable instead of chat");
   providers(i,a);
   main(i,()->call(activity,"openPermissionSettings"));SystemClock.sleep(300);main(i,()->((View)get(activity,"root")).findViewWithTag("permission-ai-microphone").performClick());
   await(i,()->{android.view.accessibility.AccessibilityNodeInfo root=i.getUiAutomation().getRootInActiveWindow();return root!=null&&!root.findAccessibilityNodeInfosByViewId("com.android.permissioncontroller:id/permission_allow_foreground_only_button").isEmpty();},"Microphone did not request the system permission");android.view.accessibility.AccessibilityNodeInfo permission=i.getUiAutomation().getRootInActiveWindow().findAccessibilityNodeInfosByViewId("com.android.permissioncontroller:id/permission_allow_foreground_only_button").get(0);permission.performAction(android.view.accessibility.AccessibilityNodeInfo.ACTION_CLICK);await(i,()->activity.checkSelfPermission(android.Manifest.permission.RECORD_AUDIO)==android.content.pm.PackageManager.PERMISSION_GRANTED,"Microphone permission was not granted");
   result.putString("result","PASS: composer IME motion, animated plus toggle and keyboard dismissal, preserved chat return/draft, encrypted multi-provider migration/edit/selection/delete, horizontal actions and system microphone prompt");result.putString("geometry","compact="+compact+" expanded="+expanded+" distinctHeights="+new HashSet<>(heights).size());code=Activity.RESULT_OK;
  }catch(Throwable e){java.io.StringWriter trace=new java.io.StringWriter();e.printStackTrace(new java.io.PrintWriter(trace));result.putString("result","FAIL: "+trace);}
  finally{if(a!=null){MainActivity activity=a;main(i,activity::finish);}i.finish(code,result);}
 }
}
